-- 覆盖：截至 2023 年全部 5 批国家级非遗代表性项目 + 国家级代表性传承人
-- 规模：类别 10、项目 1557、传承人 3057
-- 依赖：需先执行 00_schema.sql
-- 执行：mysql -u root -p dsh_ich < 10_ich_seed_data.sql
-- ============================================================================

SET NAMES utf8mb4;
START TRANSACTION;

-- 清理既有种子数据（保留用户、角色等基础表）
DELETE FROM `ich_project_inheritor`;
DELETE FROM `ich_project`;
DELETE FROM `ich_inheritor`;
DELETE FROM `ich_category`;

