-- ---------------------------------------------------------------------------
-- 校验
-- ---------------------------------------------------------------------------
SELECT '类别' AS 表, COUNT(*) AS 条数 FROM `ich_category`
UNION ALL SELECT '非遗项目', COUNT(*) FROM `ich_project`
UNION ALL SELECT '传承人',   COUNT(*) FROM `ich_inheritor`;